# -*- coding: utf-8 -*-
"""Class 10 Science Chapter 10 Simulator JavaScript Handlers"""

SIMULATOR_JS = "\n// Chapter 10: The Human Eye and the Colourful World - Simulators Engine\n\n// Global animation timer handles\nlet sim13AnimHandle = null;\nlet sim14AnimHandle = null;\n\nfunction initSimulator(id) {\n    if (sim13AnimHandle) { cancelAnimationFrame(sim13AnimHandle); sim13AnimHandle = null; }\n    if (sim14AnimHandle) { cancelAnimationFrame(sim14AnimHandle); sim14AnimHandle = null; }\n\n    switch(id) {\n        case 1: sim1Init(); break;\n        case 2: sim2Init(); break;\n        case 3: sim3Init(); break;\n        case 4: sim4Init(); break;\n        case 5: sim5Init(); break;\n        case 6: sim6Init(); break;\n        case 7: sim7Init(); break;\n        case 8: sim8Init(); break;\n        case 9: sim9Init(); break;\n        case 10: sim10Init(); break;\n        case 11: sim11Init(); break;\n        case 12: sim12Init(); break;\n        case 13: sim13Init(); break;\n        case 14: sim14Init(); break;\n        case 15: sim15Init(); break;\n        case 16: sim16Init(); break;\n    }\n}\n\n// -------------------------------------------------------------\n// Simulator 1: Eye vs Camera Optics\n// -------------------------------------------------------------\nlet sim1Mode = 'eye';\n\nfunction sim1SetMode(mode) {\n    sim1Mode = mode;\n    const btnEye = document.getElementById('sim1_btn_eye');\n    const btnCam = document.getElementById('sim1_btn_cam');\n    if (mode === 'eye') {\n        if (btnEye) { btnEye.className = 'px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold'; }\n        if (btnCam) { btnCam.className = 'px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium'; }\n        document.getElementById('sim1_val_front').textContent = 'Cornea (n=1.376)';\n        document.getElementById('sim1_val_aperture').textContent = 'Iris & Pupil';\n        document.getElementById('sim1_val_lens').textContent = 'Crystalline Lens';\n        document.getElementById('sim1_val_screen').textContent = 'Retina (Real, Inverted)';\n    } else {\n        if (btnCam) { btnCam.className = 'px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold'; }\n        if (btnEye) { btnEye.className = 'px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium'; }\n        document.getElementById('sim1_val_front').textContent = 'Protective Lens Cover';\n        document.getElementById('sim1_val_aperture').textContent = 'Mechanical Diaphragm';\n        document.getElementById('sim1_val_lens').textContent = 'Glass Lens System';\n        document.getElementById('sim1_val_screen').textContent = 'Sensor / Film (Inverted)';\n    }\n    sim1Update();\n}\n\nfunction sim1Init() {\n    sim1Update();\n}\n\nfunction sim1Update() {\n    const canvas = document.getElementById('sim1_canvas');\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n    const w = canvas.width;\n    const h = canvas.height;\n    ctx.clearRect(0, 0, w, h);\n\n    const lightVal = parseInt(document.getElementById('sim1_light_slider')?.value || 70) / 100;\n\n    // Optical Axis\n    ctx.strokeStyle = 'rgba(100, 116, 139, 0.4)';\n    ctx.setLineDash([5, 5]);\n    ctx.lineWidth = 1;\n    ctx.beginPath();\n    ctx.moveTo(30, h/2);\n    ctx.lineTo(w - 30, h/2);\n    ctx.stroke();\n    ctx.setLineDash([]);\n\n    // Object (Candle) at left\n    const objX = 70;\n    const objH = 70;\n    // Candle body\n    ctx.fillStyle = '#f59e0b';\n    ctx.fillRect(objX - 6, h/2 - objH + 15, 12, objH - 15);\n    // Candle flame\n    ctx.beginPath();\n    ctx.fillStyle = '#ef4444';\n    ctx.ellipse(objX, h/2 - objH + 8, 5, 10, 0, 0, Math.PI * 2);\n    ctx.fill();\n    ctx.beginPath();\n    ctx.fillStyle = '#fbbf24';\n    ctx.ellipse(objX, h/2 - objH + 9, 3, 6, 0, 0, Math.PI * 2);\n    ctx.fill();\n\n    const deviceX = 340;\n    const deviceR = 85;\n\n    if (sim1Mode === 'eye') {\n        // Eyeball outline\n        ctx.beginPath();\n        ctx.arc(deviceX, h/2, deviceR, -Math.PI * 0.4, Math.PI * 0.4, false);\n        ctx.strokeStyle = '#38bdf8';\n        ctx.lineWidth = 3;\n        ctx.stroke();\n\n        // Cornea bulge\n        ctx.beginPath();\n        ctx.arc(deviceX - 55, h/2, 45, -Math.PI * 0.35, Math.PI * 0.35, false);\n        ctx.strokeStyle = '#38bdf8';\n        ctx.lineWidth = 3;\n        ctx.stroke();\n\n        // Iris\n        const pupilHalf = 12 * (1.2 - lightVal * 0.4);\n        ctx.fillStyle = '#d97706';\n        ctx.fillRect(deviceX - 22, h/2 - 40, 6, 40 - pupilHalf);\n        ctx.fillRect(deviceX - 22, h/2 + pupilHalf, 6, 40 - pupilHalf);\n\n        // Crystalline Lens\n        ctx.beginPath();\n        ctx.ellipse(deviceX - 10, h/2, 12, 38, 0, 0, Math.PI * 2);\n        ctx.fillStyle = 'rgba(56, 189, 248, 0.25)';\n        ctx.strokeStyle = '#0284c7';\n        ctx.lineWidth = 2;\n        ctx.fill();\n        ctx.stroke();\n\n        // Retina screen\n        ctx.beginPath();\n        ctx.arc(deviceX, h/2, deviceR - 3, -Math.PI * 0.35, Math.PI * 0.35, false);\n        ctx.strokeStyle = '#f43f5e';\n        ctx.lineWidth = 4;\n        ctx.stroke();\n\n        // Optic nerve stump\n        ctx.fillStyle = '#f59e0b';\n        ctx.fillRect(deviceX + deviceR - 6, h/2 - 12, 28, 24);\n\n    } else {\n        // Camera body box\n        ctx.strokeStyle = '#94a3b8';\n        ctx.lineWidth = 3;\n        ctx.strokeRect(deviceX - 40, h/2 - 75, 130, 150);\n\n        // Lens cylinder\n        ctx.fillStyle = 'rgba(148, 163, 184, 0.2)';\n        ctx.fillRect(deviceX - 60, h/2 - 45, 20, 90);\n        ctx.strokeRect(deviceX - 60, h/2 - 45, 20, 90);\n\n        // Camera lens glass\n        ctx.beginPath();\n        ctx.ellipse(deviceX - 40, h/2, 8, 40, 0, 0, Math.PI * 2);\n        ctx.fillStyle = 'rgba(56, 189, 248, 0.3)';\n        ctx.strokeStyle = '#38bdf8';\n        ctx.lineWidth = 2;\n        ctx.fill();\n        ctx.stroke();\n\n        // Sensor screen\n        ctx.fillStyle = '#22c55e';\n        ctx.fillRect(deviceX + 75, h/2 - 50, 6, 100);\n    }\n\n    // Light rays tracing from candle tip\n    const screenX = deviceX + (sim1Mode === 'eye' ? deviceR - 5 : 75);\n    const tipY = h/2 - objH + 8;\n    const invTipY = h/2 + (objH - 8) * 0.45;\n\n    ctx.lineWidth = 1.5;\n    ctx.strokeStyle = `rgba(251, 191, 36, ${0.4 + lightVal * 0.5})`;\n\n    // Ray 1: Top to screen\n    ctx.beginPath();\n    ctx.moveTo(objX, tipY);\n    ctx.lineTo(deviceX - 15, tipY * 0.7 + h/2 * 0.3);\n    ctx.lineTo(screenX, invTipY);\n    ctx.stroke();\n\n    // Ray 2: Middle ray through optical center\n    ctx.beginPath();\n    ctx.moveTo(objX, tipY);\n    ctx.lineTo(deviceX - 10, h/2);\n    ctx.lineTo(screenX, invTipY);\n    ctx.stroke();\n\n    // Inverted image on retina\n    const invH = (objH - 15) * 0.45;\n    ctx.fillStyle = '#f59e0b';\n    ctx.fillRect(screenX - 4, h/2, 8, invH);\n    ctx.beginPath();\n    ctx.fillStyle = '#ef4444';\n    ctx.ellipse(screenX, invTipY, 3, 5, 0, 0, Math.PI * 2);\n    ctx.fill();\n\n    // Labels\n    ctx.font = '10px Inter, sans-serif';\n    ctx.fillStyle = '#94a3b8';\n    ctx.fillText('Object (Candle)', objX - 25, h/2 + 25);\n    ctx.fillStyle = '#f43f5e';\n    ctx.fillText(sim1Mode === 'eye' ? 'Retina (Inverted Image)' : 'Sensor (Inverted Image)', screenX - 60, h/2 + invH + 20);\n}\n\n// -------------------------------------------------------------\n// Simulator 2: Anatomy & Pupillary Light Reflex\n// -------------------------------------------------------------\nlet sim2ShowLabels = true;\n\nfunction sim2ToggleLabels() {\n    sim2ShowLabels = !sim2ShowLabels;\n    const btn = document.getElementById('sim2_btn_lbl');\n    if (btn) btn.textContent = sim2ShowLabels ? 'Hide Anatomical Labels' : 'Show Anatomical Labels';\n    sim2Update();\n}\n\nfunction sim2Init() {\n    sim2Update();\n}\n\nfunction sim2Update() {\n    const canvas = document.getElementById('sim2_canvas');\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n    const w = canvas.width;\n    const h = canvas.height;\n    ctx.clearRect(0, 0, w, h);\n\n    const luxVal = parseInt(document.getElementById('sim2_lux_slider')?.value || 50);\n    const pupilDiamMm = (6.0 - (luxVal / 100) * 4.0).toFixed(1);\n    document.getElementById('sim2_pupil_diam').textContent = `${pupilDiamMm} mm`;\n\n    let stateStr = 'Balanced Tone';\n    let fluxStr = 'Optimal Safe';\n    if (luxVal > 75) {\n        stateStr = 'Sphincter Contracted (Constricted)';\n        fluxStr = 'Glare Shielded';\n    } else if (luxVal < 30) {\n        stateStr = 'Dilator Contracted (Dilated)';\n        fluxStr = 'Maximizing Light Influx';\n    }\n    document.getElementById('sim2_muscle_state').textContent = stateStr;\n    document.getElementById('sim2_flux_txt').textContent = fluxStr;\n    document.getElementById('sim2_lux_txt').textContent = `${luxVal}% (${luxVal > 70 ? 'Bright' : luxVal < 35 ? 'Dim' : 'Normal'})`;\n\n    const cx = w / 2 - 20;\n    const cy = h / 2;\n    const r = 90;\n\n    // Sclera / Outer wall\n    ctx.beginPath();\n    ctx.arc(cx, cy, r, -Math.PI * 0.42, Math.PI * 0.42, false);\n    ctx.lineWidth = 6;\n    ctx.strokeStyle = '#e2e8f0';\n    ctx.stroke();\n\n    // Choroid middle vascular layer\n    ctx.beginPath();\n    ctx.arc(cx, cy, r - 4, -Math.PI * 0.40, Math.PI * 0.40, false);\n    ctx.lineWidth = 3;\n    ctx.strokeStyle = '#78350f';\n    ctx.stroke();\n\n    // Retina inner layer\n    ctx.beginPath();\n    ctx.arc(cx, cy, r - 7, -Math.PI * 0.38, Math.PI * 0.38, false);\n    ctx.lineWidth = 3;\n    ctx.strokeStyle = '#f43f5e';\n    ctx.stroke();\n\n    // Cornea\n    ctx.beginPath();\n    ctx.arc(cx - 58, cy, 50, -Math.PI * 0.36, Math.PI * 0.36, false);\n    ctx.lineWidth = 4;\n    ctx.strokeStyle = '#38bdf8';\n    ctx.stroke();\n\n    // Aqueous Chamber\n    ctx.fillStyle = 'rgba(56, 189, 248, 0.08)';\n    ctx.beginPath();\n    ctx.arc(cx - 58, cy, 48, -Math.PI * 0.36, Math.PI * 0.36, false);\n    ctx.fill();\n\n    // Iris diaphragm (changes size based on pupil)\n    const pupilPixelHalf = 7 + (pupilDiamMm / 6) * 16;\n    ctx.fillStyle = '#b45309';\n    // Top iris\n    ctx.fillRect(cx - 24, cy - 45, 8, 45 - pupilPixelHalf);\n    // Bottom iris\n    ctx.fillRect(cx - 24, cy + pupilPixelHalf, 8, 45 - pupilPixelHalf);\n\n    // Crystalline Lens\n    ctx.beginPath();\n    ctx.ellipse(cx - 10, cy, 14, 42, 0, 0, Math.PI * 2);\n    ctx.fillStyle = 'rgba(56, 189, 248, 0.3)';\n    ctx.strokeStyle = '#0284c7';\n    ctx.lineWidth = 2;\n    ctx.fill();\n    ctx.stroke();\n\n    // Vitreous Humor text\n    ctx.font = '11px Inter, sans-serif';\n    ctx.fillStyle = 'rgba(148, 163, 184, 0.6)';\n    ctx.fillText('Vitreous Humor (n ≈ 1.336)', cx + 5, cy + 5);\n\n    // Incoming light rays\n    const rayAlpha = 0.3 + (luxVal / 100) * 0.6;\n    ctx.strokeStyle = `rgba(251, 191, 36, ${rayAlpha})`;\n    ctx.lineWidth = 2;\n    for (let dy of [-pupilPixelHalf * 0.8, 0, pupilPixelHalf * 0.8]) {\n        ctx.beginPath();\n        ctx.moveTo(30, cy + dy * 1.5);\n        ctx.lineTo(cx - 20, cy + dy);\n        ctx.lineTo(cx + r - 10, cy);\n        ctx.stroke();\n    }\n\n    if (sim2ShowLabels) {\n        ctx.font = '10px Inter, sans-serif';\n        ctx.fillStyle = '#38bdf8';\n        ctx.fillText('Cornea', cx - 95, cy - 50);\n        ctx.fillStyle = '#d97706';\n        ctx.fillText('Iris', cx - 20, cy - 50);\n        ctx.fillStyle = '#fbbf24';\n        ctx.fillText(`Pupil (${pupilDiamMm}mm)`, cx - 35, cy + pupilPixelHalf + 18);\n        ctx.fillStyle = '#0284c7';\n        ctx.fillText('Crystalline Lens', cx - 15, cy - 58);\n        ctx.fillStyle = '#f43f5e';\n        ctx.fillText('Retina Screen', cx + r - 30, cy - 70);\n        ctx.fillStyle = '#94a3b8';\n        ctx.fillText('Optic Nerve', cx + r + 10, cy + 4);\n    }\n}\n\n// -------------------------------------------------------------\n// Simulator 3: Retina Photoreceptors & Transduction\n// -------------------------------------------------------------\nlet sim3Mode = 'bright';\n\nfunction sim3SetMode(mode) {\n    sim3Mode = mode;\n    const btnD = document.getElementById('sim3_btn_dim');\n    const btnB = document.getElementById('sim3_btn_bright');\n    if (mode === 'dim') {\n        if (btnD) btnD.className = 'px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold';\n        if (btnB) btnB.className = 'px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium';\n        document.getElementById('sim3_active_type').textContent = 'Rod Cells (~120M active)';\n        document.getElementById('sim3_perception_txt').textContent = 'Scotopic Night (Monochrome)';\n        document.getElementById('sim3_potential_txt').textContent = '-65 mV (Hyperpolarized)';\n    } else {\n        if (btnB) btnB.className = 'px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold';\n        if (btnD) btnD.className = 'px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium';\n        document.getElementById('sim3_active_type').textContent = 'Cone Cells (~6M active)';\n        document.getElementById('sim3_perception_txt').textContent = 'Photopic Trichromatic Acuity';\n        document.getElementById('sim3_potential_txt').textContent = '-40 mV (Transduced)';\n    }\n    sim3Update();\n}\n\nfunction sim3Init() {\n    sim3Update();\n}\n\nfunction sim3Update() {\n    const canvas = document.getElementById('sim3_canvas');\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n    const w = canvas.width;\n    const h = canvas.height;\n    ctx.clearRect(0, 0, w, h);\n\n    const filterVal = document.getElementById('sim3_color_select')?.value || 'white';\n\n    // Background layers of retina\n    ctx.fillStyle = 'rgba(30, 41, 59, 0.4)';\n    ctx.fillRect(40, 20, w - 80, h - 40);\n\n    // Pigment Epithelium back wall\n    ctx.fillStyle = '#0f172a';\n    ctx.fillRect(w - 70, 20, 30, h - 40);\n    ctx.font = '10px Inter, sans-serif';\n    ctx.fillStyle = '#64748b';\n    ctx.save();\n    ctx.translate(w - 50, h/2);\n    ctx.rotate(Math.PI/2);\n    ctx.fillText('Pigment Epithelium', -45, 0);\n    ctx.restore();\n\n    // Draw Photoreceptors (Rods & Cones)\n    const receptorX = w - 140;\n    const numCells = 8;\n    const cellSpacing = 26;\n\n    for (let i = 0; i < numCells; i++) {\n        const y = 35 + i * cellSpacing;\n        const isCone = (i % 2 === 0);\n\n        if (isCone) {\n            // Cone shape\n            ctx.beginPath();\n            ctx.moveTo(receptorX, y - 6);\n            ctx.lineTo(receptorX + 45, y);\n            ctx.lineTo(receptorX, y + 6);\n            ctx.closePath();\n\n            let coneColor = '#3b82f6';\n            if (filterVal === 'red') coneColor = '#ef4444';\n            else if (filterVal === 'green') coneColor = '#22c55e';\n\n            ctx.fillStyle = (sim3Mode === 'bright') ? coneColor : 'rgba(100, 116, 139, 0.5)';\n            ctx.fill();\n            ctx.strokeStyle = '#94a3b8';\n            ctx.lineWidth = 1;\n            ctx.stroke();\n        } else {\n            // Rod shape (cylindrical)\n            ctx.fillStyle = (sim3Mode === 'dim') ? '#38bdf8' : 'rgba(100, 116, 139, 0.4)';\n            ctx.fillRect(receptorX, y - 5, 45, 10);\n            ctx.strokeStyle = '#94a3b8';\n            ctx.lineWidth = 1;\n            ctx.strokeRect(receptorX, y - 5, 45, 10);\n        }\n    }\n\n    // Bipolar Neurons\n    const bipolarX = w - 240;\n    for (let i = 0; i < 4; i++) {\n        const by = 50 + i * 50;\n        ctx.fillStyle = '#a855f7';\n        ctx.beginPath();\n        ctx.arc(bipolarX, by, 8, 0, Math.PI * 2);\n        ctx.fill();\n        // Axons to receptors\n        ctx.strokeStyle = 'rgba(168, 85, 247, 0.5)';\n        ctx.lineWidth = 2;\n        ctx.beginPath();\n        ctx.moveTo(bipolarX, by);\n        ctx.lineTo(receptorX, by - 12);\n        ctx.moveTo(bipolarX, by);\n        ctx.lineTo(receptorX, by + 12);\n        ctx.stroke();\n    }\n\n    // Ganglion Cells & Optic Nerve Fiber bundle\n    const ganglionX = 140;\n    ctx.fillStyle = '#10b981';\n    for (let i = 0; i < 3; i++) {\n        const gy = 60 + i * 65;\n        ctx.beginPath();\n        ctx.arc(ganglionX, gy, 12, 0, Math.PI * 2);\n        ctx.fill();\n\n        // Synapses to bipolar\n        ctx.strokeStyle = 'rgba(16, 185, 129, 0.5)';\n        ctx.lineWidth = 2;\n        ctx.beginPath();\n        ctx.moveTo(ganglionX, gy);\n        ctx.lineTo(bipolarX, gy - 15);\n        ctx.stroke();\n\n        // Action potential wave into optic nerve\n        ctx.strokeStyle = '#fbbf24';\n        ctx.lineWidth = 3;\n        ctx.beginPath();\n        ctx.moveTo(ganglionX, gy);\n        ctx.lineTo(50, gy);\n        ctx.stroke();\n    }\n\n    // Incoming photons\n    let photonColor = '#f8fafc';\n    if (filterVal === 'red') photonColor = '#f87171';\n    else if (filterVal === 'green') photonColor = '#4ade80';\n    else if (filterVal === 'blue') photonColor = '#60a5fa';\n\n    ctx.fillStyle = photonColor;\n    for (let i = 0; i < 12; i++) {\n        const px = 70 + (i * 35) % 180;\n        const py = 35 + ((i * 47) % (h - 70));\n        ctx.beginPath();\n        ctx.arc(px, py, 3, 0, Math.PI * 2);\n        ctx.fill();\n    }\n\n    ctx.font = '10px Inter, sans-serif';\n    ctx.fillStyle = '#fbbf24';\n    ctx.fillText('← Light Impulses (Photons)', 60, h - 25);\n    ctx.fillStyle = '#10b981';\n    ctx.fillText('Ganglion Cells', ganglionX - 35, 30);\n    ctx.fillStyle = '#a855f7';\n    ctx.fillText('Bipolar Layer', bipolarX - 30, 30);\n    ctx.fillStyle = '#38bdf8';\n    ctx.fillText('Rods & Cones Layer', receptorX - 20, 25);\n}\n\n// -------------------------------------------------------------\n// Simulator 4: Power of Accommodation\n// -------------------------------------------------------------\nfunction sim4SetDist(val) {\n    const slider = document.getElementById('sim4_dist_slider');\n    if (slider) slider.value = val;\n    sim4Update();\n}\n\nfunction sim4Init() {\n    sim4Update();\n}\n\nfunction sim4Update() {\n    const canvas = document.getElementById('sim4_canvas');\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n    const w = canvas.width;\n    const h = canvas.height;\n    ctx.clearRect(0, 0, w, h);\n\n    const u = parseInt(document.getElementById('sim4_dist_slider')?.value || 100);\n    document.getElementById('sim4_dist_txt').textContent = (u >= 280) ? 'Infinity (∞)' : `${u} cm`;\n\n    let muscleStr = 'Relaxed (Thin Lens)';\n    let thickStr = 'Stretched Thin';\n    let focalCm = 2.27;\n    let statusStr = 'Sharp Distant Focus';\n\n    if (u < 25) {\n        muscleStr = 'Maximally Strained!';\n        thickStr = 'Maximum Bulge Limit';\n        focalCm = 2.15;\n        statusStr = 'Eyestrain / Blurred (&lt;25cm)';\n    } else if (u < 60) {\n        muscleStr = 'Contracted Inward';\n        thickStr = 'Bulged Thick';\n        focalCm = 2.18;\n        statusStr = 'Sharp Near Focus';\n    } else if (u < 200) {\n        muscleStr = 'Partially Contracted';\n        thickStr = 'Moderate Bulge';\n        focalCm = 2.22;\n        statusStr = 'Comfortable Focus';\n    }\n\n    document.getElementById('sim4_muscle_txt').textContent = muscleStr;\n    document.getElementById('sim4_lens_thick').textContent = thickStr;\n    document.getElementById('sim4_focal_txt').textContent = `${focalCm} cm`;\n    const statEl = document.getElementById('sim4_focus_status');\n    if (statEl) {\n        statEl.textContent = statusStr;\n        statEl.className = (u < 25) ? 'text-rose-400 font-bold' : 'text-emerald-400 font-bold';\n    }\n\n    const eyeX = 420;\n    const eyeR = 85;\n\n    // Optical Axis\n    ctx.strokeStyle = 'rgba(100, 116, 139, 0.4)';\n    ctx.setLineDash([5, 5]);\n    ctx.lineWidth = 1;\n    ctx.beginPath();\n    ctx.moveTo(30, h/2);\n    ctx.lineTo(w - 30, h/2);\n    ctx.stroke();\n    ctx.setLineDash([]);\n\n    // Eyeball\n    ctx.beginPath();\n    ctx.arc(eyeX, h/2, eyeR, -Math.PI * 0.42, Math.PI * 0.42, false);\n    ctx.strokeStyle = '#38bdf8';\n    ctx.lineWidth = 3;\n    ctx.stroke();\n\n    // Cornea\n    ctx.beginPath();\n    ctx.arc(eyeX - 55, h/2, 45, -Math.PI * 0.35, Math.PI * 0.35, false);\n    ctx.strokeStyle = '#38bdf8';\n    ctx.lineWidth = 3;\n    ctx.stroke();\n\n    // Retina\n    ctx.beginPath();\n    ctx.arc(eyeX, h/2, eyeR - 4, -Math.PI * 0.36, Math.PI * 0.36, false);\n    ctx.strokeStyle = '#f43f5e';\n    ctx.lineWidth = 4;\n    ctx.stroke();\n\n    // Ciliary muscles & Lens dynamic thickness\n    const lensThickness = 8 + (300 - Math.min(u, 300)) * 0.05;\n    const lensYRadius = 42 - (300 - Math.min(u, 300)) * 0.02;\n\n    // Ciliary muscle pads (top & bottom)\n    const ciliaryBulge = (300 - Math.min(u, 300)) * 0.04;\n    ctx.fillStyle = (u < 25) ? '#ef4444' : '#eab308';\n    ctx.fillRect(eyeX - 16, h/2 - 45 - ciliaryBulge, 16, 12 + ciliaryBulge);\n    ctx.fillRect(eyeX - 16, h/2 + 33, 16, 12 + ciliaryBulge);\n\n    // Crystalline Lens\n    ctx.beginPath();\n    ctx.ellipse(eyeX - 8, h/2, lensThickness, lensYRadius, 0, 0, Math.PI * 2);\n    ctx.fillStyle = 'rgba(56, 189, 248, 0.3)';\n    ctx.strokeStyle = '#0284c7';\n    ctx.lineWidth = 2;\n    ctx.fill();\n    ctx.stroke();\n\n    // Object (Pencil/Book)\n    const objPos = (u >= 280) ? 50 : Math.max(50, 420 - u * 1.15);\n    ctx.fillStyle = '#10b981';\n    ctx.fillRect(objPos - 4, h/2 - 40, 8, 40);\n    // Tip\n    ctx.beginPath();\n    ctx.moveTo(objPos - 4, h/2 - 40);\n    ctx.lineTo(objPos + 4, h/2 - 40);\n    ctx.lineTo(objPos, h/2 - 50);\n    ctx.fillStyle = '#f59e0b';\n    ctx.fill();\n\n    // Rays tracing\n    ctx.lineWidth = 1.5;\n    ctx.strokeStyle = (u < 25) ? 'rgba(244, 63, 94, 0.7)' : 'rgba(251, 191, 36, 0.7)';\n\n    const retinaX = eyeX + eyeR - 5;\n    const focusX = (u < 25) ? retinaX + 20 : retinaX; // Focus behind retina if strain\n\n    ctx.beginPath();\n    ctx.moveTo(objPos, h/2 - 45);\n    ctx.lineTo(eyeX - 8, h/2 - 25);\n    ctx.lineTo(focusX, h/2 + 20);\n    ctx.stroke();\n\n    ctx.beginPath();\n    ctx.moveTo(objPos, h/2 - 45);\n    ctx.lineTo(eyeX - 8, h/2 + 25);\n    ctx.lineTo(focusX, h/2 + 20);\n    ctx.stroke();\n\n    // Labels\n    ctx.font = '10px Inter, sans-serif';\n    ctx.fillStyle = '#10b981';\n    ctx.fillText(u >= 280 ? 'Distant Object (∞)' : `Object (${u}cm)`, objPos - 20, h/2 + 25);\n    ctx.fillStyle = '#eab308';\n    ctx.fillText('Ciliary Muscle', eyeX - 25, h/2 - 52);\n}\n\n// -------------------------------------------------------------\n// Simulator 5: Myopia & Concave Lens Correction\n// -------------------------------------------------------------\nlet sim5Corrected = false;\n\nfunction sim5ToggleCorrection() {\n    sim5Corrected = !sim5Corrected;\n    const btn = document.getElementById('sim5_toggle_lens');\n    if (btn) {\n        btn.textContent = sim5Corrected ? 'Remove Concave Lens' : 'Apply Concave Lens';\n        btn.className = sim5Corrected ? 'px-3 py-1 rounded-lg bg-rose-600 text-white font-bold' : 'px-3 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold';\n    }\n    sim5Update();\n}\n\nfunction sim5Init() {\n    sim5Update();\n}\n\nfunction sim5Update() {\n    const canvas = document.getElementById('sim5_canvas');\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n    const w = canvas.width;\n    const h = canvas.height;\n    ctx.clearRect(0, 0, w, h);\n\n    const fpCm = parseInt(document.getElementById('sim5_fp_slider')?.value || 100);\n    document.getElementById('sim5_fp_txt').textContent = `${fpCm} cm`;\n    const reqPower = (-100 / fpCm).toFixed(2);\n    document.getElementById('sim5_power_txt').textContent = `${reqPower} D`;\n\n    if (sim5Corrected) {\n        document.getElementById('sim5_conv_txt').textContent = 'Sharp on Retina (Corrected)';\n        document.getElementById('sim5_conv_txt').className = 'text-emerald-400 font-bold';\n        document.getElementById('sim5_acuity_txt').textContent = 'Crystal-Clear Distance Vision';\n    } else {\n        document.getElementById('sim5_conv_txt').textContent = 'In Front of Retina (Premature)';\n        document.getElementById('sim5_conv_txt').className = 'text-rose-400 font-bold';\n        document.getElementById('sim5_acuity_txt').textContent = 'Blurred Distance Object';\n    }\n\n    const eyeX = 400;\n    const eyeR = 95; // Elongated eyeball\n\n    // Axis\n    ctx.strokeStyle = 'rgba(100, 116, 139, 0.4)';\n    ctx.setLineDash([5, 5]);\n    ctx.beginPath();\n    ctx.moveTo(30, h/2);\n    ctx.lineTo(w - 30, h/2);\n    ctx.stroke();\n    ctx.setLineDash([]);\n\n    // Eyeball (Elongated oval)\n    ctx.beginPath();\n    ctx.ellipse(eyeX, h/2, eyeR, 75, 0, -Math.PI * 0.45, Math.PI * 0.45, false);\n    ctx.strokeStyle = '#38bdf8';\n    ctx.lineWidth = 3;\n    ctx.stroke();\n\n    // Cornea\n    ctx.beginPath();\n    ctx.arc(eyeX - 65, h/2, 45, -Math.PI * 0.35, Math.PI * 0.35, false);\n    ctx.strokeStyle = '#38bdf8';\n    ctx.lineWidth = 3;\n    ctx.stroke();\n\n    // Retina\n    ctx.beginPath();\n    ctx.ellipse(eyeX, h/2, eyeR - 4, 71, 0, -Math.PI * 0.38, Math.PI * 0.38, false);\n    ctx.strokeStyle = '#f43f5e';\n    ctx.lineWidth = 4;\n    ctx.stroke();\n\n    // Eye Lens\n    ctx.beginPath();\n    ctx.ellipse(eyeX - 15, h/2, 14, 40, 0, 0, Math.PI * 2);\n    ctx.fillStyle = 'rgba(56, 189, 248, 0.3)';\n    ctx.strokeStyle = '#0284c7';\n    ctx.lineWidth = 2;\n    ctx.fill();\n    ctx.stroke();\n\n    // Spectacle Lens position\n    const specX = eyeX - 100;\n    if (sim5Corrected) {\n        // Draw Concave Spectacle Lens\n        ctx.fillStyle = 'rgba(168, 85, 247, 0.3)';\n        ctx.strokeStyle = '#a855f7';\n        ctx.lineWidth = 2;\n        ctx.beginPath();\n        ctx.moveTo(specX - 6, h/2 - 45);\n        ctx.lineTo(specX + 6, h/2 - 45);\n        ctx.quadraticCurveTo(specX + 2, h/2, specX + 6, h/2 + 45);\n        ctx.lineTo(specX - 6, h/2 + 45);\n        ctx.quadraticCurveTo(specX - 2, h/2, specX - 6, h/2 - 45);\n        ctx.fill();\n        ctx.stroke();\n\n        ctx.font = '10px Inter, sans-serif';\n        ctx.fillStyle = '#a855f7';\n        ctx.fillText(`Concave (${reqPower}D)`, specX - 30, h/2 - 52);\n    }\n\n    // Parallel rays from distant object\n    const startX = 40;\n    const rayYs = [h/2 - 30, h/2 - 15, h/2 + 15, h/2 + 30];\n    const retinaX = eyeX + eyeR - 5;\n    const uncorrFocusX = eyeX + 45; // Premature focus in front\n\n    ctx.lineWidth = 1.5;\n\n    rayYs.forEach(ry => {\n        ctx.strokeStyle = 'rgba(251, 191, 36, 0.8)';\n        ctx.beginPath();\n        ctx.moveTo(startX, ry);\n\n        if (sim5Corrected) {\n            // Ray reaches spectacle lens, diverges slightly\n            ctx.lineTo(specX, ry);\n            const divY = ry + (ry > h/2 ? 5 : -5);\n            ctx.lineTo(eyeX - 15, divY);\n            ctx.lineTo(retinaX, h/2);\n        } else {\n            // Parallel directly to eye lens, over-converges\n            ctx.lineTo(eyeX - 15, ry);\n            ctx.lineTo(uncorrFocusX, h/2);\n            // Continues diverging to retina\n            ctx.lineTo(retinaX, h/2 + (ry > h/2 ? -18 : 18));\n        }\n        ctx.stroke();\n    });\n\n    // Convergence indicator\n    ctx.beginPath();\n    ctx.arc(sim5Corrected ? retinaX : uncorrFocusX, h/2, 4, 0, Math.PI * 2);\n    ctx.fillStyle = sim5Corrected ? '#10b981' : '#f43f5e';\n    ctx.fill();\n\n    ctx.font = '10px Inter, sans-serif';\n    ctx.fillStyle = sim5Corrected ? '#10b981' : '#f43f5e';\n    ctx.fillText(sim5Corrected ? 'Focused on Retina' : 'Focused in Front of Retina', (sim5Corrected ? retinaX : uncorrFocusX) - 50, h/2 + 35);\n}\n\n// -------------------------------------------------------------\n// Simulator 6: Hypermetropia & Convex Lens Correction\n// -------------------------------------------------------------\nlet sim6Corrected = false;\n\nfunction sim6ToggleCorrection() {\n    sim6Corrected = !sim6Corrected;\n    const btn = document.getElementById('sim6_toggle_lens');\n    if (btn) {\n        btn.textContent = sim6Corrected ? 'Remove Convex Lens' : 'Apply Convex Lens';\n        btn.className = sim6Corrected ? 'px-3 py-1 rounded-lg bg-rose-600 text-white font-bold' : 'px-3 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold';\n    }\n    sim6Update();\n}\n\nfunction sim6Init() {\n    sim6Update();\n}\n\nfunction sim6Update() {\n    const canvas = document.getElementById('sim6_canvas');\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n    const w = canvas.width;\n    const h = canvas.height;\n    ctx.clearRect(0, 0, w, h);\n\n    const npCm = parseInt(document.getElementById('sim6_np_slider')?.value || 75);\n    document.getElementById('sim6_np_txt').textContent = `${npCm} cm`;\n    // P = 1/0.25 - 1/(np/100) = 4 - 100/np\n    const reqPower = (4.0 - 100.0 / npCm).toFixed(2);\n    document.getElementById('sim6_power_txt').textContent = `+${reqPower} D`;\n\n    if (sim6Corrected) {\n        document.getElementById('sim6_conv_txt').textContent = 'Sharp on Retina (Corrected)';\n        document.getElementById('sim6_conv_txt').className = 'text-emerald-400 font-bold';\n        document.getElementById('sim6_acuity_txt').textContent = 'Clear 25 cm Reading';\n    } else {\n        document.getElementById('sim6_conv_txt').textContent = 'Behind Retina (Under-converged)';\n        document.getElementById('sim6_conv_txt').className = 'text-rose-400 font-bold';\n        document.getElementById('sim6_acuity_txt').textContent = 'Blurred Close-Up Vision';\n    }\n\n    const eyeX = 420;\n    const eyeR = 75; // Short eyeball\n\n    // Axis\n    ctx.strokeStyle = 'rgba(100, 116, 139, 0.4)';\n    ctx.setLineDash([5, 5]);\n    ctx.beginPath();\n    ctx.moveTo(30, h/2);\n    ctx.lineTo(w - 30, h/2);\n    ctx.stroke();\n    ctx.setLineDash([]);\n\n    // Eyeball (Compressed / short)\n    ctx.beginPath();\n    ctx.ellipse(eyeX, h/2, eyeR, 82, 0, -Math.PI * 0.42, Math.PI * 0.42, false);\n    ctx.strokeStyle = '#38bdf8';\n    ctx.lineWidth = 3;\n    ctx.stroke();\n\n    // Cornea\n    ctx.beginPath();\n    ctx.arc(eyeX - 52, h/2, 45, -Math.PI * 0.35, Math.PI * 0.35, false);\n    ctx.strokeStyle = '#38bdf8';\n    ctx.lineWidth = 3;\n    ctx.stroke();\n\n    // Retina\n    ctx.beginPath();\n    ctx.ellipse(eyeX, h/2, eyeR - 4, 78, 0, -Math.PI * 0.36, Math.PI * 0.36, false);\n    ctx.strokeStyle = '#f43f5e';\n    ctx.lineWidth = 4;\n    ctx.stroke();\n\n    // Eye Lens\n    ctx.beginPath();\n    ctx.ellipse(eyeX - 10, h/2, 10, 38, 0, 0, Math.PI * 2);\n    ctx.fillStyle = 'rgba(56, 189, 248, 0.3)';\n    ctx.strokeStyle = '#0284c7';\n    ctx.lineWidth = 2;\n    ctx.fill();\n    ctx.stroke();\n\n    // Near Object (25 cm)\n    const objX = 140;\n    ctx.fillStyle = '#10b981';\n    ctx.fillRect(objX - 3, h/2 - 30, 6, 30);\n    ctx.font = '10px Inter, sans-serif';\n    ctx.fillText('Near Object (25 cm)', objX - 45, h/2 + 25);\n\n    // Spectacle Lens position\n    const specX = eyeX - 80;\n    if (sim6Corrected) {\n        // Draw Convex Spectacle Lens\n        ctx.fillStyle = 'rgba(16, 185, 129, 0.3)';\n        ctx.strokeStyle = '#10b981';\n        ctx.lineWidth = 2;\n        ctx.beginPath();\n        ctx.ellipse(specX, h/2, 6, 42, 0, 0, Math.PI * 2);\n        ctx.fill();\n        ctx.stroke();\n\n        ctx.fillStyle = '#10b981';\n        ctx.fillText(`Convex (+${reqPower}D)`, specX - 25, h/2 - 50);\n    }\n\n    const retinaX = eyeX + eyeR - 5;\n    const behindFocusX = eyeX + eyeR + 35; // Extends behind retina\n\n    ctx.lineWidth = 1.5;\n    ctx.strokeStyle = 'rgba(251, 191, 36, 0.8)';\n\n    // Diverging rays from reading object\n    [-25, 0, 25].forEach(dy => {\n        ctx.beginPath();\n        ctx.moveTo(objX, h/2 - 25);\n\n        if (sim6Corrected) {\n            // Convex lens pre-converges\n            ctx.lineTo(specX, h/2 + dy * 0.8);\n            ctx.lineTo(eyeX - 10, h/2 + dy * 0.5);\n            ctx.lineTo(retinaX, h/2);\n        } else {\n            // Diverges directly to eye lens, under-converges\n            ctx.lineTo(eyeX - 10, h/2 + dy);\n            ctx.lineTo(retinaX, h/2 + dy * 0.3);\n            ctx.stroke();\n            // Virtual dotted continuation behind retina\n            ctx.setLineDash([3, 3]);\n            ctx.strokeStyle = 'rgba(244, 63, 94, 0.5)';\n            ctx.beginPath();\n            ctx.moveTo(retinaX, h/2 + dy * 0.3);\n            ctx.lineTo(behindFocusX, h/2);\n        }\n        ctx.stroke();\n        ctx.setLineDash([]);\n    });\n\n    // Convergence spot\n    ctx.beginPath();\n    ctx.arc(sim6Corrected ? retinaX : behindFocusX, h/2, 4, 0, Math.PI * 2);\n    ctx.fillStyle = sim6Corrected ? '#10b981' : '#f43f5e';\n    ctx.fill();\n\n    ctx.fillStyle = sim6Corrected ? '#10b981' : '#f43f5e';\n    ctx.fillText(sim6Corrected ? 'Focused on Retina' : 'Focused Behind Retina', (sim6Corrected ? retinaX - 50 : behindFocusX - 45), h/2 + 25);\n}\n\n// -------------------------------------------------------------\n// Simulator 7: Presbyopia & Bi-Focal Studio\n// -------------------------------------------------------------\nlet sim7Gaze = 'distance';\n\nfunction sim7SetGaze(gaze) {\n    sim7Gaze = gaze;\n    const btnD = document.getElementById('sim7_btn_dist');\n    const btnN = document.getElementById('sim7_btn_near');\n    if (gaze === 'distance') {\n        if (btnD) btnD.className = 'px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold';\n        if (btnN) btnN.className = 'px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium';\n        document.getElementById('sim7_zone_txt').textContent = 'Upper Concave Segment';\n        document.getElementById('sim7_zone_txt').className = 'text-amber-400 font-bold';\n    } else {\n        if (btnN) btnN.className = 'px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold';\n        if (btnD) btnD.className = 'px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium';\n        document.getElementById('sim7_zone_txt').textContent = 'Lower Convex Segment';\n        document.getElementById('sim7_zone_txt').className = 'text-emerald-400 font-bold';\n    }\n    sim7Update();\n}\n\nfunction sim7Init() {\n    sim7Update();\n}\n\nfunction sim7Update() {\n    const canvas = document.getElementById('sim7_canvas');\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n    const w = canvas.width;\n    const h = canvas.height;\n    ctx.clearRect(0, 0, w, h);\n\n    const age = parseInt(document.getElementById('sim7_age_slider')?.value || 55);\n    document.getElementById('sim7_age_txt').textContent = `${age} yrs`;\n\n    const addPower = (+1.0 + (age - 40) * 0.05).toFixed(2);\n    document.getElementById('sim7_rx_txt').textContent = `-1.50 D / +${addPower} D`;\n\n    // Draw Bi-focal spectacle lens in large profile\n    const lensX = 180;\n    const lensY = h / 2;\n    const lensW = 70;\n    const lensH = 180;\n\n    // Outer spectacle rim\n    ctx.strokeStyle = '#475569';\n    ctx.lineWidth = 4;\n    ctx.strokeRect(lensX - lensW/2, lensY - lensH/2, lensW, lensH);\n\n    // Upper Concave Zone (Distance)\n    ctx.fillStyle = (sim7Gaze === 'distance') ? 'rgba(56, 189, 248, 0.25)' : 'rgba(56, 189, 248, 0.08)';\n    ctx.fillRect(lensX - lensW/2 + 2, lensY - lensH/2 + 2, lensW - 4, lensH/2 - 2);\n\n    // Lower Convex Zone (Reading)\n    ctx.fillStyle = (sim7Gaze === 'reading') ? 'rgba(16, 185, 129, 0.3)' : 'rgba(16, 185, 129, 0.08)';\n    ctx.beginPath();\n    ctx.ellipse(lensX, lensY + 45, 28, 35, 0, 0, Math.PI * 2);\n    ctx.fill();\n    ctx.strokeStyle = '#10b981';\n    ctx.lineWidth = 2;\n    ctx.stroke();\n\n    // Dividing line\n    ctx.strokeStyle = '#94a3b8';\n    ctx.setLineDash([4, 4]);\n    ctx.beginPath();\n    ctx.moveTo(lensX - lensW/2, lensY);\n    ctx.lineTo(lensX + lensW/2, lensY);\n    ctx.stroke();\n    ctx.setLineDash([]);\n\n    // Eyeball profile to the right\n    const eyeX = 420;\n    const eyeY = (sim7Gaze === 'distance') ? h/2 - 20 : h/2 + 25;\n    ctx.beginPath();\n    ctx.arc(eyeX, eyeY, 65, -Math.PI * 0.4, Math.PI * 0.4, false);\n    ctx.strokeStyle = '#38bdf8';\n    ctx.lineWidth = 3;\n    ctx.stroke();\n\n    // Pupil\n    ctx.fillStyle = '#0f172a';\n    ctx.beginPath();\n    ctx.ellipse(eyeX - 45, eyeY, 4, 12, 0, 0, Math.PI * 2);\n    ctx.fill();\n\n    // Ray tracing based on gaze\n    ctx.lineWidth = 2;\n    if (sim7Gaze === 'distance') {\n        // Horizontal parallel distance rays\n        ctx.strokeStyle = 'rgba(56, 189, 248, 0.8)';\n        ctx.beginPath();\n        ctx.moveTo(30, lensY - 45);\n        ctx.lineTo(lensX, lensY - 45);\n        ctx.lineTo(eyeX - 45, eyeY);\n        ctx.lineTo(eyeX + 60, eyeY);\n        ctx.stroke();\n\n        ctx.beginPath();\n        ctx.moveTo(30, lensY - 20);\n        ctx.lineTo(lensX, lensY - 20);\n        ctx.lineTo(eyeX - 45, eyeY);\n        ctx.lineTo(eyeX + 60, eyeY);\n        ctx.stroke();\n    } else {\n        // Downward angled rays from book\n        ctx.strokeStyle = 'rgba(16, 185, 129, 0.8)';\n        ctx.beginPath();\n        ctx.moveTo(50, lensY + 70);\n        ctx.lineTo(lensX, lensY + 45);\n        ctx.lineTo(eyeX - 45, eyeY);\n        ctx.lineTo(eyeX + 60, eyeY);\n        ctx.stroke();\n\n        ctx.beginPath();\n        ctx.moveTo(50, lensY + 50);\n        ctx.lineTo(lensX, lensY + 30);\n        ctx.lineTo(eyeX - 45, eyeY);\n        ctx.lineTo(eyeX + 60, eyeY);\n        ctx.stroke();\n    }\n\n    // Text descriptions\n    ctx.font = '11px Inter, sans-serif';\n    ctx.fillStyle = '#38bdf8';\n    ctx.fillText('Upper: Concave (Distance Vision)', lensX - 70, lensY - lensH/2 - 8);\n    ctx.fillStyle = '#10b981';\n    ctx.fillText(`Lower: Convex Reading (+${addPower}D)`, lensX - 70, lensY + lensH/2 + 18);\n    ctx.fillStyle = '#94a3b8';\n    ctx.fillText(sim7Gaze === 'distance' ? 'Straight-Ahead Gaze' : 'Downward Reading Gaze', eyeX - 40, eyeY - 75);\n}\n\n// -------------------------------------------------------------\n// Simulator 8: Prism Refraction Goniometer\n// -------------------------------------------------------------\nfunction sim8Init() {\n    sim8Update();\n}\n\nfunction sim8Update() {\n    const canvas = document.getElementById('sim8_canvas');\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n    const w = canvas.width;\n    const h = canvas.height;\n    ctx.clearRect(0, 0, w, h);\n\n    const iDeg = parseInt(document.getElementById('sim8_i_slider')?.value || 48);\n    const aDeg = parseInt(document.getElementById('sim8_a_slider')?.value || 60);\n    document.getElementById('sim8_i_txt').textContent = `${iDeg}°`;\n    document.getElementById('sim8_a_txt').textContent = `${aDeg}°`;\n\n    const n = 1.50; // Glass\n    const iRad = (iDeg * Math.PI) / 180;\n    const aRad = (aDeg * Math.PI) / 180;\n\n    // Snell's Law at 1st face: sin(i) = n * sin(r1)\n    const sinR1 = Math.sin(iRad) / n;\n    const r1Rad = Math.asin(sinR1);\n    const r1Deg = (r1Rad * 180) / Math.PI;\n\n    // r2 = A - r1\n    const r2Rad = aRad - r1Rad;\n    const r2Deg = (r2Rad * 180) / Math.PI;\n\n    // Snell's Law at 2nd face: n * sin(r2) = sin(e)\n    let eDeg = 0;\n    let dDeg = 0;\n    const sinE = n * Math.sin(r2Rad);\n\n    if (sinE <= 1.0) {\n        const eRad = Math.asin(sinE);\n        eDeg = (eRad * 180) / Math.PI;\n        // D = i + e - A\n        dDeg = iDeg + eDeg - aDeg;\n    } else {\n        // Total internal reflection inside prism\n        eDeg = 90;\n        dDeg = 90;\n    }\n\n    document.getElementById('sim8_e_txt').textContent = `${eDeg.toFixed(1)}°`;\n    document.getElementById('sim8_d_txt').textContent = `${dDeg.toFixed(1)}°`;\n    document.getElementById('sim8_sum_txt').textContent = `${iDeg}° + ${eDeg.toFixed(1)}° = ${aDeg}° + ${dDeg.toFixed(1)}°`;\n\n    // Draw Triangular Prism\n    const cx = w / 2;\n    const cy = h / 2 + 15;\n    const side = 180;\n    const halfA = aRad / 2;\n\n    const apexX = cx;\n    const apexY = cy - side * Math.cos(halfA) * 0.7;\n    const b1X = cx - side * Math.sin(halfA);\n    const b1Y = cy + side * Math.cos(halfA) * 0.5;\n    const b2X = cx + side * Math.sin(halfA);\n    const b2Y = cy + side * Math.cos(halfA) * 0.5;\n\n    // Prism body\n    ctx.beginPath();\n    ctx.moveTo(apexX, apexY);\n    ctx.lineTo(b1X, b1Y);\n    ctx.lineTo(b2X, b2Y);\n    ctx.closePath();\n    ctx.fillStyle = 'rgba(56, 189, 248, 0.15)';\n    ctx.strokeStyle = '#38bdf8';\n    ctx.lineWidth = 2.5;\n    ctx.fill();\n    ctx.stroke();\n\n    // Incident point E on face 1\n    const t1 = 0.55;\n    const pE_x = apexX * (1 - t1) + b1X * t1;\n    const pE_y = apexY * (1 - t1) + b1Y * t1;\n\n    // Emergent point F on face 2\n    const t2 = 0.60;\n    const pF_x = apexX * (1 - t2) + b2X * t2;\n    const pF_y = apexY * (1 - t2) + b2Y * t2;\n\n    // Normals\n    ctx.setLineDash([4, 4]);\n    ctx.strokeStyle = '#64748b';\n    ctx.lineWidth = 1;\n    // Normal 1\n    ctx.beginPath();\n    ctx.moveTo(pE_x - 40 * Math.cos(halfA), pE_y - 40 * Math.sin(halfA));\n    ctx.lineTo(pE_x + 40 * Math.cos(halfA), pE_y + 40 * Math.sin(halfA));\n    ctx.stroke();\n\n    // Incident Ray\n    const incLen = 120;\n    const incStartX = pE_x - incLen * Math.cos(iRad - halfA);\n    const incStartY = pE_y - incLen * Math.sin(iRad - halfA);\n\n    ctx.setLineDash([]);\n    ctx.strokeStyle = '#fbbf24';\n    ctx.lineWidth = 2.5;\n    ctx.beginPath();\n    ctx.moveTo(incStartX, incStartY);\n    ctx.lineTo(pE_x, pE_y);\n    ctx.lineTo(pF_x, pF_y);\n\n    // Emergent Ray\n    const emLen = 130;\n    const emEndX = pF_x + emLen * Math.cos(halfA - (eDeg * Math.PI)/180);\n    const emEndY = pF_y + emLen * Math.sin((eDeg * Math.PI)/180);\n    ctx.lineTo(emEndX, emEndY);\n    ctx.stroke();\n\n    // Extended rays to show Deviation Angle D\n    ctx.setLineDash([3, 3]);\n    ctx.strokeStyle = 'rgba(244, 63, 94, 0.7)';\n    ctx.lineWidth = 1.5;\n    // Incident produced forward\n    ctx.beginPath();\n    ctx.moveTo(pE_x, pE_y);\n    ctx.lineTo(pE_x + 140 * Math.cos(iRad - halfA), pE_y + 140 * Math.sin(iRad - halfA));\n    ctx.stroke();\n\n    // Emergent produced backward\n    ctx.beginPath();\n    ctx.moveTo(pF_x, pF_y);\n    ctx.lineTo(pF_x - 100 * Math.cos(halfA - (eDeg * Math.PI)/180), pF_y - 100 * Math.sin((eDeg * Math.PI)/180));\n    ctx.stroke();\n    ctx.setLineDash([]);\n\n    // Labels\n    ctx.font = '11px Inter, sans-serif';\n    ctx.fillStyle = '#38bdf8';\n    ctx.fillText(`Apex A (${aDeg}°)`, apexX - 25, apexY - 10);\n    ctx.fillStyle = '#fbbf24';\n    ctx.fillText(`i = ${iDeg}°`, pE_x - 55, pE_y - 15);\n    ctx.fillStyle = '#2dd4bf';\n    ctx.fillText(`e = ${eDeg.toFixed(1)}°`, pF_x + 15, pF_y + 20);\n    ctx.fillStyle = '#f43f5e';\n    ctx.fillText(`Deviation D = ${dDeg.toFixed(1)}°`, cx + 30, cy - 25);\n}\n\n// -------------------------------------------------------------\n// Simulator 9: Prism Dispersion & VIBGYOR Spectrum\n// -------------------------------------------------------------\nlet sim9Source = 'white';\n\nfunction sim9SetSource(src) {\n    sim9Source = src;\n    const btnW = document.getElementById('sim9_btn_white');\n    const btnM = document.getElementById('sim9_btn_mono');\n    if (src === 'white') {\n        if (btnW) btnW.className = 'px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold';\n        if (btnM) btnM.className = 'px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium';\n        document.getElementById('sim9_disp_txt').textContent = 'Δθ ≈ 1.85° (VIBGYOR)';\n    } else {\n        if (btnM) btnM.className = 'px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold';\n        if (btnW) btnW.className = 'px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium';\n        document.getElementById('sim9_disp_txt').textContent = '0° (Single Green Line)';\n    }\n    sim9Update();\n}\n\nfunction sim9Init() {\n    sim9Update();\n}\n\nfunction sim9Update() {\n    const canvas = document.getElementById('sim9_canvas');\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n    const w = canvas.width;\n    const h = canvas.height;\n    ctx.clearRect(0, 0, w, h);\n\n    const beamW = parseInt(document.getElementById('sim9_width_slider')?.value || 6);\n\n    // Prism\n    const px = 260;\n    const py = h / 2 + 20;\n    ctx.beginPath();\n    ctx.moveTo(px, py - 95);\n    ctx.lineTo(px - 75, py + 55);\n    ctx.lineTo(px + 75, py + 55);\n    ctx.closePath();\n    ctx.fillStyle = 'rgba(56, 189, 248, 0.18)';\n    ctx.strokeStyle = '#38bdf8';\n    ctx.lineWidth = 2.5;\n    ctx.fill();\n    ctx.stroke();\n\n    // Incident Beam (White or Green)\n    ctx.lineWidth = beamW;\n    ctx.strokeStyle = (sim9Source === 'white') ? '#ffffff' : '#22c55e';\n    ctx.beginPath();\n    ctx.moveTo(30, py - 15);\n    ctx.lineTo(px - 35, py - 15);\n    ctx.stroke();\n\n    // White Screen on right\n    ctx.fillStyle = '#f8fafc';\n    ctx.fillRect(w - 45, 30, 8, h - 60);\n    ctx.font = '10px Inter, sans-serif';\n    ctx.fillStyle = '#94a3b8';\n    ctx.fillText('White Display Screen', w - 120, 25);\n\n    if (sim9Source === 'white') {\n        // Disperse into 7 VIBGYOR colors\n        const colors = [\n            { name: 'Red', hex: '#ef4444', devY: 10 },\n            { name: 'Orange', hex: '#f97316', devY: 18 },\n            { name: 'Yellow', hex: '#eab308', devY: 26 },\n            { name: 'Green', hex: '#22c55e', devY: 34 },\n            { name: 'Blue', hex: '#3b82f6', devY: 42 },\n            { name: 'Indigo', hex: '#6366f1', devY: 50 },\n            { name: 'Violet', hex: '#a855f7', devY: 58 }\n        ];\n\n        colors.forEach((c, idx) => {\n            ctx.lineWidth = 2;\n            ctx.strokeStyle = c.hex;\n\n            // Inside prism\n            ctx.beginPath();\n            ctx.moveTo(px - 35, py - 15);\n            const insideY = py - 15 + idx * 2.2;\n            ctx.lineTo(px + 20, insideY);\n\n            // To screen\n            const screenY = py - 35 + c.devY * 1.5;\n            ctx.lineTo(w - 45, screenY);\n            ctx.stroke();\n\n            // Screen patch\n            ctx.fillStyle = c.hex;\n            ctx.fillRect(w - 45, screenY - 3, 8, 6);\n            ctx.fillText(c.name, w - 30, screenY + 3);\n        });\n    } else {\n        // Monochromatic green\n        ctx.lineWidth = 2.5;\n        ctx.strokeStyle = '#22c55e';\n        ctx.beginPath();\n        ctx.moveTo(px - 35, py - 15);\n        ctx.lineTo(px + 20, py - 7);\n        ctx.lineTo(w - 45, py + 20);\n        ctx.stroke();\n\n        ctx.fillStyle = '#22c55e';\n        ctx.fillRect(w - 45, py + 17, 8, 6);\n        ctx.fillText('532 nm Green', w - 30, py + 23);\n    }\n}\n\n// -------------------------------------------------------------\n// Simulator 10: Newton Recombination Apparatus\n// -------------------------------------------------------------\nlet sim10P2Active = true;\n\nfunction sim10ToggleP2() {\n    sim10P2Active = !sim10P2Active;\n    const btn = document.getElementById('sim10_toggle_p2');\n    if (btn) {\n        btn.textContent = sim10P2Active ? 'Inverted P2 Active' : 'Remove Inverted P2';\n        btn.className = sim10P2Active ? 'px-3 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold' : 'px-3 py-1 rounded-lg bg-slate-800 text-slate-300 font-medium';\n    }\n    document.getElementById('sim10_p2_action').textContent = sim10P2Active ? 'Equal & Opposite Recombination' : 'None (Spectrum Continues)';\n    document.getElementById('sim10_screen_txt').textContent = sim10P2Active ? 'Pure White Sunlight' : 'Dispersed VIBGYOR Spectrum';\n    sim10Update();\n}\n\nfunction sim10Init() {\n    sim10Update();\n}\n\nfunction sim10Update() {\n    const canvas = document.getElementById('sim10_canvas');\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n    const w = canvas.width;\n    const h = canvas.height;\n    ctx.clearRect(0, 0, w, h);\n\n    const sep = parseInt(document.getElementById('sim10_sep_slider')?.value || 80);\n\n    // Prism 1 (Upright)\n    const p1x = 180;\n    const p1y = h / 2 + 15;\n    ctx.beginPath();\n    ctx.moveTo(p1x, p1y - 80);\n    ctx.lineTo(p1x - 60, p1y + 50);\n    ctx.lineTo(p1x + 60, p1y + 50);\n    ctx.closePath();\n    ctx.fillStyle = 'rgba(56, 189, 248, 0.15)';\n    ctx.strokeStyle = '#38bdf8';\n    ctx.lineWidth = 2;\n    ctx.fill();\n    ctx.stroke();\n\n    // Incident White sunlight\n    ctx.lineWidth = 5;\n    ctx.strokeStyle = '#ffffff';\n    ctx.beginPath();\n    ctx.moveTo(30, p1y - 15);\n    ctx.lineTo(p1x - 28, p1y - 15);\n    ctx.stroke();\n\n    // Screen\n    ctx.fillStyle = '#f8fafc';\n    ctx.fillRect(w - 40, 30, 8, h - 60);\n\n    const p2x = p1x + sep + 60;\n    const p2y = h / 2 + 15;\n\n    if (sim10P2Active) {\n        // Prism 2 (Inverted - apex pointing DOWN)\n        ctx.beginPath();\n        ctx.moveTo(p2x, p2y + 60);\n        ctx.lineTo(p2x - 60, p2y - 70);\n        ctx.lineTo(p2x + 60, p2y - 70);\n        ctx.closePath();\n        ctx.fillStyle = 'rgba(168, 85, 247, 0.15)';\n        ctx.strokeStyle = '#a855f7';\n        ctx.lineWidth = 2;\n        ctx.fill();\n        ctx.stroke();\n\n        // Dispersed rays from P1 to P2\n        ['#ef4444', '#a855f7'].forEach((col, idx) => {\n            const dy = (idx === 0) ? -5 : 12;\n            ctx.lineWidth = 2;\n            ctx.strokeStyle = col;\n            ctx.beginPath();\n            ctx.moveTo(p1x + 18, p1y - 15 + dy * 0.5);\n            ctx.lineTo(p2x - 25, p2y - 15 + dy * 1.5);\n            ctx.stroke();\n        });\n\n        // Inside P2 and emerging recombined white beam\n        ctx.lineWidth = 4;\n        ctx.strokeStyle = '#ffffff';\n        ctx.beginPath();\n        ctx.moveTo(p2x + 22, p2y);\n        ctx.lineTo(w - 40, p2y + 5);\n        ctx.stroke();\n\n        ctx.fillStyle = '#ffffff';\n        ctx.fillRect(w - 40, p2y - 5, 8, 20);\n\n        ctx.font = '10px Inter, sans-serif';\n        ctx.fillStyle = '#a855f7';\n        ctx.fillText('Inverted P2 (Recombiner)', p2x - 50, p2y - 78);\n    } else {\n        // Dispersed spectrum spreads directly to screen\n        ['#ef4444', '#f97316', '#eab308', '#22c55e', '#3b82f6', '#a855f7'].forEach((col, idx) => {\n            ctx.lineWidth = 2;\n            ctx.strokeStyle = col;\n            ctx.beginPath();\n            ctx.moveTo(p1x + 18, p1y - 15 + idx * 4);\n            ctx.lineTo(w - 40, p1y - 45 + idx * 18);\n            ctx.stroke();\n        });\n    }\n\n    ctx.font = '10px Inter, sans-serif';\n    ctx.fillStyle = '#38bdf8';\n    ctx.fillText('P1 (Disperser)', p1x - 30, p1y - 88);\n}\n\n// -------------------------------------------------------------\n// Simulator 11: Rainbow Droplet Optics\n// -------------------------------------------------------------\nlet sim11Stage = 'all';\n\nfunction sim11SetStage(st) {\n    sim11Stage = st;\n    ['all', '1', '2', '3'].forEach(k => {\n        const b = document.getElementById(`sim11_btn_${k}`);\n        if (b) {\n            b.className = (k === st) ? 'px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold' : 'px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300';\n        }\n    });\n    sim11Update();\n}\n\nfunction sim11Init() {\n    sim11Update();\n}\n\nfunction sim11Update() {\n    const canvas = document.getElementById('sim11_canvas');\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n    const w = canvas.width;\n    const h = canvas.height;\n    ctx.clearRect(0, 0, w, h);\n\n    const dropX = w / 2 - 20;\n    const dropY = h / 2 - 5;\n    const dropR = 85;\n\n    // Water Droplet (Sphere)\n    ctx.beginPath();\n    ctx.arc(dropX, dropY, dropR, 0, Math.PI * 2);\n    ctx.fillStyle = 'rgba(56, 189, 248, 0.12)';\n    ctx.strokeStyle = '#38bdf8';\n    ctx.lineWidth = 3;\n    ctx.fill();\n    ctx.stroke();\n\n    // Incoming sunlight ray at top boundary\n    const inY = dropY - 55;\n    const hitX = dropX - Math.sqrt(dropR*dropR - 55*55);\n\n    ctx.lineWidth = 3;\n    ctx.strokeStyle = '#ffffff';\n    ctx.beginPath();\n    ctx.moveTo(30, inY);\n    ctx.lineTo(hitX, inY);\n    ctx.stroke();\n    ctx.font = '10px Inter, sans-serif';\n    ctx.fillStyle = '#ffffff';\n    ctx.fillText('Sunlight (White)', 40, inY - 8);\n\n    // Stage 1: Refract & Disperse inside drop\n    const backRedX = dropX + dropR * 0.95;\n    const backRedY = dropY + 15;\n    const backVioX = dropX + dropR * 0.88;\n    const backVioY = dropY - 8;\n\n    if (sim11Stage === 'all' || sim11Stage === '1' || sim11Stage === '2' || sim11Stage === '3') {\n        // Red ray\n        ctx.strokeStyle = '#ef4444';\n        ctx.lineWidth = 2;\n        ctx.beginPath();\n        ctx.moveTo(hitX, inY);\n        ctx.lineTo(backRedX, backRedY);\n        ctx.stroke();\n\n        // Violet ray\n        ctx.strokeStyle = '#a855f7';\n        ctx.beginPath();\n        ctx.moveTo(hitX, inY);\n        ctx.lineTo(backVioX, backVioY);\n        ctx.stroke();\n    }\n\n    // Stage 2: Internal Reflection\n    const exitRedX = dropX - dropR * 0.55;\n    const exitRedY = dropY + dropR * 0.83;\n    const exitVioX = dropX - dropR * 0.40;\n    const exitVioY = dropY + dropR * 0.91;\n\n    if (sim11Stage === 'all' || sim11Stage === '2' || sim11Stage === '3') {\n        ctx.strokeStyle = '#ef4444';\n        ctx.beginPath();\n        ctx.moveTo(backRedX, backRedY);\n        ctx.lineTo(exitRedX, exitRedY);\n        ctx.stroke();\n\n        ctx.strokeStyle = '#a855f7';\n        ctx.beginPath();\n        ctx.moveTo(backVioX, backVioY);\n        ctx.lineTo(exitVioX, exitVioY);\n        ctx.stroke();\n    }\n\n    // Stage 3: Refraction on emergence towards observer\n    if (sim11Stage === 'all' || sim11Stage === '3') {\n        // Red ray emerges at 42 deg\n        ctx.strokeStyle = '#ef4444';\n        ctx.beginPath();\n        ctx.moveTo(exitRedX, exitRedY);\n        ctx.lineTo(exitRedX - 140, exitRedY + 60);\n        ctx.stroke();\n\n        // Violet ray emerges at 40 deg\n        ctx.strokeStyle = '#a855f7';\n        ctx.beginPath();\n        ctx.moveTo(exitVioX, exitVioY);\n        ctx.lineTo(exitVioX - 140, exitVioY + 50);\n        ctx.stroke();\n\n        ctx.fillStyle = '#ef4444';\n        ctx.fillText('Red (42.0°)', exitRedX - 110, exitRedY + 80);\n        ctx.fillStyle = '#a855f7';\n        ctx.fillText('Violet (40.2°)', exitVioX - 110, exitVioY + 58);\n    }\n}\n\n// -------------------------------------------------------------\n// Simulator 12: Atmospheric Gradient Ray Tracer\n// -------------------------------------------------------------\nlet sim12AtmNormal = true;\n\nfunction sim12ToggleAtmosphere() {\n    sim12AtmNormal = !sim12AtmNormal;\n    const btn = document.getElementById('sim12_toggle_atm');\n    if (btn) {\n        btn.textContent = sim12AtmNormal ? 'Normal Atmosphere' : 'No Atmosphere (Vacuum)';\n        btn.className = sim12AtmNormal ? 'px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold' : 'px-2.5 py-1 rounded-lg bg-slate-800 text-slate-300 font-medium';\n    }\n    document.getElementById('sim12_path_txt').textContent = sim12AtmNormal ? 'Curved Downward Arc' : 'Straight Geometric Line';\n    sim12Update();\n}\n\nfunction sim12Init() {\n    sim12Update();\n}\n\nfunction sim12Update() {\n    const canvas = document.getElementById('sim12_canvas');\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n    const w = canvas.width;\n    const h = canvas.height;\n    ctx.clearRect(0, 0, w, h);\n\n    const thetaDeg = parseInt(document.getElementById('sim12_angle_slider')?.value || 45);\n    document.getElementById('sim12_angle_txt').textContent = `${thetaDeg}°`;\n\n    // Atmospheric stratified density layers\n    const numLayers = 6;\n    const layerH = (h - 60) / numLayers;\n\n    for (let i = 0; i < numLayers; i++) {\n        const y = 30 + i * layerH;\n        const density = 0.05 + (i / numLayers) * 0.25;\n        ctx.fillStyle = sim12AtmNormal ? `rgba(56, 189, 248, ${density})` : 'rgba(15, 23, 42, 0.4)';\n        ctx.fillRect(40, y, w - 80, layerH);\n        ctx.strokeStyle = 'rgba(100, 116, 139, 0.3)';\n        ctx.strokeRect(40, y, w - 80, layerH);\n    }\n\n    // Earth Surface Ground\n    ctx.fillStyle = '#065f46';\n    ctx.fillRect(40, h - 30, w - 80, 20);\n    ctx.font = '10px Inter, sans-serif';\n    ctx.fillStyle = '#6ee7b7';\n    ctx.fillText('Earth Surface (Denser Air, n=1.00029)', 55, h - 16);\n\n    // Observer at bottom right\n    const obsX = w - 160;\n    const obsY = h - 35;\n    ctx.fillStyle = '#f59e0b';\n    ctx.beginPath();\n    ctx.arc(obsX, obsY, 6, 0, Math.PI * 2);\n    ctx.fill();\n\n    // Light ray tracing\n    const startX = 80;\n    const startY = 30;\n\n    ctx.lineWidth = 2.5;\n    ctx.strokeStyle = '#fbbf24';\n    ctx.beginPath();\n    ctx.moveTo(startX, startY);\n\n    if (sim12AtmNormal) {\n        // Continuous downward curve bending towards normal\n        ctx.quadraticCurveTo((startX + obsX) / 2 - 40, (startY + obsY) / 2 + 50, obsX, obsY);\n    } else {\n        // Straight line in vacuum\n        ctx.lineTo(obsX, obsY);\n    }\n    ctx.stroke();\n\n    // Apparent elevated position tangent\n    if (sim12AtmNormal) {\n        ctx.setLineDash([4, 4]);\n        ctx.strokeStyle = 'rgba(244, 63, 94, 0.8)';\n        ctx.beginPath();\n        ctx.moveTo(obsX, obsY);\n        ctx.lineTo(startX + 80, startY - 10);\n        ctx.stroke();\n        ctx.setLineDash([]);\n\n        ctx.fillStyle = '#f43f5e';\n        ctx.fillText('Apparent Elevated Position (Virtual)', startX + 70, startY - 15);\n    }\n\n    ctx.fillStyle = '#fbbf24';\n    ctx.fillText('Celestial Light Ray', startX - 20, startY - 5);\n}\n\n// -------------------------------------------------------------\n// Simulator 13: Star Twinkling vs Planet\n// -------------------------------------------------------------\nlet sim13Source = 'star';\nlet sim13Frame = 0;\n\nfunction sim13SetSource(src) {\n    sim13Source = src;\n    const btnS = document.getElementById('sim13_btn_star');\n    const btnP = document.getElementById('sim13_btn_planet');\n    if (src === 'star') {\n        if (btnS) btnS.className = 'px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold';\n        if (btnP) btnP.className = 'px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium';\n        document.getElementById('sim13_geo_txt').textContent = 'Sub-Microscopic Point';\n        document.getElementById('sim13_pos_txt').textContent = 'Elevated & Fluctuating';\n        document.getElementById('sim13_lum_txt').textContent = 'Twinkling Rapidly';\n        document.getElementById('sim13_avg_txt').textContent = 'No Cancellation (Single Ray)';\n    } else {\n        if (btnP) btnP.className = 'px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold';\n        if (btnS) btnS.className = 'px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium';\n        document.getElementById('sim13_geo_txt').textContent = 'Extended Disk (Proximity)';\n        document.getElementById('sim13_pos_txt').textContent = 'Stable Fixed Coordinate';\n        document.getElementById('sim13_lum_txt').textContent = 'Constant Steady Glow';\n        document.getElementById('sim13_avg_txt').textContent = 'Variations Average to Zero';\n    }\n}\n\nfunction sim13Init() {\n    function loop() {\n        sim13Update();\n        sim13Frame++;\n        sim13AnimHandle = requestAnimationFrame(loop);\n    }\n    loop();\n}\n\nfunction sim13Update() {\n    const canvas = document.getElementById('sim13_canvas');\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n    const w = canvas.width;\n    const h = canvas.height;\n    ctx.clearRect(0, 0, w, h);\n\n    const turb = parseInt(document.getElementById('sim13_turb_slider')?.value || 5);\n\n    // Night Sky background with distant twinkling dust\n    ctx.fillStyle = '#020617';\n    ctx.fillRect(0, 0, w, h);\n\n    // Turbulent atmosphere boundary\n    ctx.fillStyle = 'rgba(30, 41, 59, 0.5)';\n    ctx.fillRect(0, 100, w, h - 100);\n\n    // Observer pupil at bottom center\n    const obsX = w / 2;\n    const obsY = h - 25;\n    ctx.fillStyle = '#38bdf8';\n    ctx.beginPath();\n    ctx.arc(obsX, obsY, 8, 0, Math.PI * 2);\n    ctx.fill();\n\n    if (sim13Source === 'star') {\n        // Distant Point Source Star\n        const starX = w / 2;\n        const starY = 40;\n\n        // Twinkle factor using sine wave + random noise scaled by turbulence\n        const noise = (Math.sin(sim13Frame * 0.15) * 0.4 + (Math.random() - 0.5) * 0.6) * (turb / 10);\n        const radius = Math.max(1, 4 + noise * 4);\n        const alpha = Math.max(0.2, Math.min(1.0, 0.6 + noise));\n\n        ctx.fillStyle = `rgba(251, 191, 36, ${alpha})`;\n        ctx.beginPath();\n        ctx.arc(starX, starY, radius, 0, Math.PI * 2);\n        ctx.fill();\n\n        // Ray path wavering\n        ctx.strokeStyle = `rgba(251, 191, 36, ${alpha * 0.7})`;\n        ctx.lineWidth = 1.5;\n        ctx.beginPath();\n        ctx.moveTo(starX, starY);\n        const midX = starX + (Math.sin(sim13Frame * 0.1) * turb * 3);\n        ctx.quadraticCurveTo(midX, h / 2, obsX, obsY);\n        ctx.stroke();\n\n    } else {\n        // Extended Source Planet (Cluster of points)\n        const planetX = w / 2;\n        const planetY = 45;\n        const planetR = 14;\n\n        ctx.fillStyle = '#fbbf24';\n        ctx.beginPath();\n        ctx.arc(planetX, planetY, planetR, 0, Math.PI * 2);\n        ctx.fill();\n\n        // Multiple ray paths averaging out\n        for (let i = -3; i <= 3; i++) {\n            const ox = planetX + i * 3.5;\n            ctx.strokeStyle = 'rgba(251, 191, 36, 0.25)';\n            ctx.lineWidth = 1;\n            ctx.beginPath();\n            ctx.moveTo(ox, planetY + 8);\n            ctx.lineTo(obsX, obsY);\n            ctx.stroke();\n        }\n    }\n\n    ctx.font = '10px Inter, sans-serif';\n    ctx.fillStyle = '#94a3b8';\n    ctx.fillText('Turbulent Atmospheric Layers (Fluctuating Density)', 20, 115);\n    ctx.fillText('Observer Eye', obsX - 30, obsY + 18);\n}\n\n// -------------------------------------------------------------\n// Simulator 14: Advanced Sunrise & Sunset\n// -------------------------------------------------------------\nlet sim14AnimActive = false;\n\nfunction sim14ToggleAnimation() {\n    sim14AnimActive = !sim14AnimActive;\n    const btn = document.getElementById('sim14_toggle_anim');\n    if (btn) btn.textContent = sim14AnimActive ? 'Pause Solar Cycle' : 'Animate Solar Cycle';\n    if (sim14AnimActive) sim14Init();\n}\n\nfunction sim14Init() {\n    if (sim14AnimActive && !sim14AnimHandle) {\n        function loop() {\n            const slider = document.getElementById('sim14_elev_slider');\n            if (slider && sim14AnimActive) {\n                let v = parseInt(slider.value) + 1;\n                if (v > 20) v = -20;\n                slider.value = v;\n                sim14Update();\n            }\n            if (sim14AnimActive) sim14AnimHandle = requestAnimationFrame(loop);\n        }\n        loop();\n    } else {\n        sim14Update();\n    }\n}\n\nfunction sim14Update() {\n    const canvas = document.getElementById('sim14_canvas');\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n    const w = canvas.width;\n    const h = canvas.height;\n    ctx.clearRect(0, 0, w, h);\n\n    const elevVal = parseInt(document.getElementById('sim14_elev_slider')?.value || -5) / 10;\n    document.getElementById('sim14_elev_txt').textContent = `${elevVal.toFixed(1)}° (${elevVal < 0 ? 'Below Horizon' : 'Above Horizon'})`;\n\n    const horizonY = h / 2 + 30;\n\n    // Geometric Horizon line\n    ctx.strokeStyle = '#475569';\n    ctx.lineWidth = 2;\n    ctx.setLineDash([5, 5]);\n    ctx.beginPath();\n    ctx.moveTo(20, horizonY);\n    ctx.lineTo(w - 20, horizonY);\n    ctx.stroke();\n    ctx.setLineDash([]);\n\n    // Earth Curve & Observer\n    ctx.fillStyle = '#065f46';\n    ctx.fillRect(w / 2 + 60, horizonY, 180, h - horizonY);\n    ctx.font = '10px Inter, sans-serif';\n    ctx.fillStyle = '#34d399';\n    ctx.fillText('Observer on Earth', w / 2 + 80, horizonY + 25);\n\n    // Atmospheric layer boundary\n    ctx.fillStyle = 'rgba(56, 189, 248, 0.12)';\n    ctx.fillRect(20, horizonY - 80, w - 40, 80);\n\n    // True Sun Position (Physical)\n    const trueSunX = 140;\n    const trueSunY = horizonY - elevVal * 30; // Below horizon if negative\n\n    ctx.fillStyle = '#ea580c';\n    ctx.beginPath();\n    ctx.arc(trueSunX, trueSunY, 16, 0, Math.PI * 2);\n    ctx.fill();\n\n    // Apparent Virtual Sun Position (Elevated by ~0.5 deg = 15 px)\n    const appSunY = trueSunY - 18;\n    ctx.fillStyle = '#facc15';\n    ctx.beginPath();\n    // Oval vertical compression\n    ctx.ellipse(trueSunX, appSunY, 16, 13, 0, 0, Math.PI * 2);\n    ctx.fill();\n\n    // Ray tracing curved over the horizon\n    const obsX = w / 2 + 100;\n    const obsY = horizonY;\n\n    ctx.strokeStyle = '#ea580c';\n    ctx.lineWidth = 2;\n    ctx.beginPath();\n    ctx.moveTo(trueSunX, trueSunY);\n    ctx.quadraticCurveTo(w / 2 - 20, horizonY - 40, obsX, obsY);\n    ctx.stroke();\n\n    // Tangent to apparent position\n    ctx.setLineDash([3, 3]);\n    ctx.strokeStyle = 'rgba(250, 204, 21, 0.8)';\n    ctx.beginPath();\n    ctx.moveTo(obsX, obsY);\n    ctx.lineTo(trueSunX, appSunY);\n    ctx.stroke();\n    ctx.setLineDash([]);\n\n    ctx.fillStyle = '#ea580c';\n    ctx.fillText('Actual Sun Position', trueSunX - 45, trueSunY + 30);\n    ctx.fillStyle = '#facc15';\n    ctx.fillText('Apparent Sun (Refracted)', trueSunX - 55, appSunY - 20);\n    ctx.fillStyle = '#94a3b8';\n    ctx.fillText('Geometric Horizon', 30, horizonY - 6);\n}\n\n// -------------------------------------------------------------\n// Simulator 15: Tyndall Effect Colloidal Chamber\n// -------------------------------------------------------------\nlet sim15Medium = 'colloid';\n\nfunction sim15SetMedium(m) {\n    sim15Medium = m;\n    const btnC = document.getElementById('sim15_btn_colloid');\n    const btnT = document.getElementById('sim15_btn_true');\n    if (m === 'colloid') {\n        if (btnC) btnC.className = 'px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold';\n        if (btnT) btnT.className = 'px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium';\n        document.getElementById('sim15_size_txt').textContent = '1 nm to 1000 nm (Colloid)';\n        document.getElementById('sim15_vis_txt').textContent = 'Luminous Illuminated Cone';\n        document.getElementById('sim15_vis_txt').className = 'text-teal-400 font-bold';\n    } else {\n        if (btnT) btnT.className = 'px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold';\n        if (btnC) btnC.className = 'px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium';\n        document.getElementById('sim15_size_txt').textContent = '&lt; 1 nm (True Molecular Solution)';\n        document.getElementById('sim15_vis_txt').textContent = 'Completely Invisible Path';\n        document.getElementById('sim15_vis_txt').className = 'text-slate-400 font-bold';\n    }\n    sim15Update();\n}\n\nfunction sim15Init() {\n    sim15Update();\n}\n\nfunction sim15Update() {\n    const canvas = document.getElementById('sim15_canvas');\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n    const w = canvas.width;\n    const h = canvas.height;\n    ctx.clearRect(0, 0, w, h);\n\n    const laserPower = parseInt(document.getElementById('sim15_laser_slider')?.value || 70) / 100;\n\n    // Laser Source at left\n    ctx.fillStyle = '#dc2626';\n    ctx.fillRect(30, h / 2 - 15, 50, 30);\n    ctx.fillStyle = '#f87171';\n    ctx.beginPath();\n    ctx.arc(80, h / 2, 8, 0, Math.PI * 2);\n    ctx.fill();\n\n    // Glass Beaker / Chamber\n    const bX = 140;\n    const bY = 35;\n    const bW = w - 240;\n    const bH = h - 70;\n\n    ctx.strokeStyle = '#38bdf8';\n    ctx.lineWidth = 3;\n    ctx.strokeRect(bX, bY, bW, bH);\n    ctx.fillStyle = (sim15Medium === 'colloid') ? 'rgba(56, 189, 248, 0.08)' : 'rgba(56, 189, 248, 0.03)';\n    ctx.fillRect(bX, bY, bW, bH);\n\n    // Laser Beam before beaker\n    ctx.strokeStyle = `rgba(239, 68, 68, ${laserPower})`;\n    ctx.lineWidth = 4;\n    ctx.beginPath();\n    ctx.moveTo(80, h / 2);\n    ctx.lineTo(bX, h / 2);\n    ctx.stroke();\n\n    if (sim15Medium === 'colloid') {\n        // Illuminated Scattering Cone (Tyndall Effect)\n        const grad = ctx.createLinearGradient(bX, h/2 - 15, bX + bW, h/2 + 15);\n        grad.addColorStop(0, `rgba(239, 68, 68, ${laserPower * 0.85})`);\n        grad.addColorStop(1, `rgba(239, 68, 68, ${laserPower * 0.45})`);\n\n        ctx.fillStyle = grad;\n        ctx.beginPath();\n        ctx.moveTo(bX, h / 2 - 4);\n        ctx.lineTo(bX + bW, h / 2 - 16);\n        ctx.lineTo(bX + bW, h / 2 + 16);\n        ctx.lineTo(bX, h / 2 + 4);\n        ctx.closePath();\n        ctx.fill();\n\n        // Colloidal suspended dust/milk particles\n        ctx.fillStyle = '#ffffff';\n        for (let i = 0; i < 28; i++) {\n            const px = bX + 15 + ((i * 43) % (bW - 30));\n            const py = h / 2 - 12 + ((i * 29) % 24);\n            ctx.beginPath();\n            ctx.arc(px, py, 1.8, 0, Math.PI * 2);\n            ctx.fill();\n        }\n    } else {\n        // True solution: beam is INVISIBLE inside the solution!\n        ctx.setLineDash([4, 4]);\n        ctx.strokeStyle = 'rgba(239, 68, 68, 0.15)';\n        ctx.beginPath();\n        ctx.moveTo(bX, h / 2);\n        ctx.lineTo(bX + bW, h / 2);\n        ctx.stroke();\n        ctx.setLineDash([]);\n    }\n\n    // Emerging beam exiting beaker\n    ctx.strokeStyle = `rgba(239, 68, 68, ${laserPower})`;\n    ctx.lineWidth = 4;\n    ctx.beginPath();\n    ctx.moveTo(bX + bW, h / 2);\n    ctx.lineTo(w - 40, h / 2);\n    ctx.stroke();\n\n    // Spot on screen\n    ctx.fillStyle = '#dc2626';\n    ctx.beginPath();\n    ctx.arc(w - 40, h / 2, 7, 0, Math.PI * 2);\n    ctx.fill();\n\n    ctx.font = '10px Inter, sans-serif';\n    ctx.fillStyle = '#94a3b8';\n    ctx.fillText('Laser Source', 25, h / 2 - 22);\n    ctx.fillText(sim15Medium === 'colloid' ? 'Colloid: Path Visible (Tyndall)' : 'True Solution: Path Invisible', bX + 20, bY + 20);\n}\n\n// -------------------------------------------------------------\n// Simulator 16: Rayleigh Scattering & Sky Color\n// -------------------------------------------------------------\nfunction sim16SetPreset(lambda) {\n    const slider = document.getElementById('sim16_wave_slider');\n    if (slider) slider.value = lambda;\n    sim16Update();\n}\n\nfunction sim16Init() {\n    sim16Update();\n}\n\nfunction sim16Update() {\n    const canvas = document.getElementById('sim16_canvas');\n    if (!canvas) return;\n    const ctx = canvas.getContext('2d');\n    const w = canvas.width;\n    const h = canvas.height;\n    ctx.clearRect(0, 0, w, h);\n\n    const lambdaNm = parseInt(document.getElementById('sim16_wave_slider')?.value || 450);\n\n    // Rayleigh factor: I ∝ (700 / lambda)^4 normalized to red=1.0\n    const ratio = Math.pow(700 / lambdaNm, 4);\n    document.getElementById('sim16_intensity_txt').textContent = `${ratio.toFixed(2)} × Red Baseline`;\n\n    let colorName = 'Blue';\n    let hexColor = '#3b82f6';\n    let skyTxt = 'Radiant Azure Dome';\n\n    if (lambdaNm < 425) {\n        colorName = 'Violet';\n        hexColor = '#a855f7';\n        skyTxt = 'Intense Rayleigh Scattering';\n    } else if (lambdaNm < 490) {\n        colorName = 'Blue';\n        hexColor = '#38bdf8';\n        skyTxt = 'Clear Daytime Blue Sky';\n    } else if (lambdaNm < 560) {\n        colorName = 'Green';\n        hexColor = '#22c55e';\n        skyTxt = 'Moderate Scattering';\n    } else if (lambdaNm < 620) {\n        colorName = 'Yellow / Orange';\n        hexColor = '#f59e0b';\n        skyTxt = 'Low Scattering';\n    } else {\n        colorName = 'Red';\n        hexColor = '#ef4444';\n        skyTxt = 'Least Scattered (Danger Signals)';\n    }\n\n    document.getElementById('sim16_wave_txt').textContent = `${lambdaNm} nm (${colorName})`;\n    document.getElementById('sim16_wave_txt').style.color = hexColor;\n    document.getElementById('sim16_sky_mode').textContent = skyTxt;\n\n    // Atmospheric scattering chamber display\n    const domeR = 90;\n    const domeX = w / 2;\n    const domeY = h / 2 + 10;\n\n    // Dome background representing sky\n    const domeGrad = ctx.createRadialGradient(domeX, domeY, 10, domeX, domeY, domeR);\n    domeGrad.addColorStop(0, hexColor);\n    domeGrad.addColorStop(1, '#020617');\n\n    ctx.fillStyle = domeGrad;\n    ctx.beginPath();\n    ctx.arc(domeX, domeY, domeR, Math.PI, 0, false);\n    ctx.fill();\n    ctx.strokeStyle = '#475569';\n    ctx.lineWidth = 2;\n    ctx.stroke();\n\n    // Scattering particles (N2 and O2 molecules)\n    ctx.fillStyle = '#ffffff';\n    for (let i = 0; i < 20; i++) {\n        const angle = Math.PI + (i / 20) * Math.PI;\n        const rad = 25 + ((i * 37) % (domeR - 35));\n        const mx = domeX + rad * Math.cos(angle);\n        const my = domeY + rad * Math.sin(angle);\n        ctx.beginPath();\n        ctx.arc(mx, my, 2, 0, Math.PI * 2);\n        ctx.fill();\n\n        // Scattered photon emission lines\n        if (ratio > 2.0) {\n            ctx.strokeStyle = `rgba(255, 255, 255, ${Math.min(0.6, ratio * 0.08)})`;\n            ctx.lineWidth = 1;\n            ctx.beginPath();\n            ctx.moveTo(mx, my);\n            ctx.lineTo(mx + 10, my - 10);\n            ctx.stroke();\n        }\n    }\n\n    // Direct penetrating ray (danger signal penetration)\n    ctx.lineWidth = 4;\n    ctx.strokeStyle = hexColor;\n    ctx.beginPath();\n    ctx.moveTo(40, domeY);\n    ctx.lineTo(w - 40, domeY);\n    ctx.stroke();\n\n    ctx.font = '11px Inter, sans-serif';\n    ctx.fillStyle = '#ffffff';\n    ctx.fillText(`Rayleigh Scattering Intensity: I ∝ 1/λ⁴ = ${ratio.toFixed(1)}×`, 45, 30);\n    ctx.fillStyle = '#94a3b8';\n    ctx.fillText('Ground / Observer Level', domeX - 60, domeY + 25);\n}\n"
